use quartiles::Quartiles;

fn main() {
    let data = vec![12.0, 15.0, 20.0, 25.0, 30.0, 35.0, 40.0, 45.0, 50.0];
    let quartiles = Quartiles::new(data);
    let (q1, q2, q3) = quartiles.calculate_quartiles();
    println!("Q1: {}, Q2: {}, Q3: {}", q1, q2, q3);
