```rust
use quartiles::Quartiles;

struct Quartiles {
    data: Vec<f64>,
}

impl Quartiles {
    fn new(data: Vec<f64>) -> Self {
        Quartiles { data }
    }

    fn calculate_quartiles(&self) -> (f64, f64, f64) {
        let q1 = quartiles::quartile(&self.data, 1).unwrap();
        let q2 = quartiles::quartile(&self.data, 2).unwrap();
        let q3 = quartiles::quartile(&self.data, 3).unwrap();
        (q1, q2, q3)
    }
}
```

