class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def hasPathSum(root: TreeNode, sum: int) -> bool:
    if not root:
        return False

    def helper(node, val):
        if not node:
            return False
        val -= node.val
        if node.left is None and node.right is None:
            return val == 0
        return helper(node.left, val) or helper(node.right, val)

    return helper(root, sum)
```

