import inspect

class JobManager:
    def __init__(self):
        self.queue = []

    def add_job(self, job_type, priority):
        self.queue.append((job_type, priority))

    def get_next_job(self):
        if self.queue:
            next_job = min(self.queue, key=lambda x: (x[1], self.queue.index(x)))
            self.queue.remove(next_job)
            return next_job[0]
        else:
            return None

    @classmethod
    def can_document_member(cls, member, membername, isattr, parent):
        return inspect.isclass(member) and issubclass(member, CalcJob)
