    span: Span,
}

impl SpannedError {
    /// Constructs a new SpannedError with the given message and span.
    fn new(message: &'static str, span: Span) -> SpannedError {
        SpannedError { message, span }
    }

    /// Returns a reference to the span associated with the error.
    fn get_span(&self) -> &Span {
        &self.span
    }
}

fn main() {
