        cls.loop._write_to_self()

    @classmethod
    def periodic(cls, func, *args, interval=None, **kwargs):
        @asyncio.coroutine
        def f():
            while True:
                yield from asyncio.sleep(interval)
                func(*args, **kwargs)

        cls.loop.create_task(f())
        cls.loop._write_to_self()


