import java.util.UUID;

public class AdminManagement {
    /**
     * Sets a custom login message for the admin identified by the given UUID.
     * Saves the modified admin entry to the super admin configuration and updates the index lists.
     * @param uuid The UUID of the admin entry.
     * @param customLoginMessage The custom login message to be set.
     * @return true if the custom login message is successfully set and saved; false otherwise.
     */
    public boolean setCustomLoginMessage(UUID uuid, String customLoginMessage) {
        AdminEntry adminEntry = AdminList.getEntry(uuid);
        if (adminEntry != null) {
            adminEntry.setCustomLoginMessage(customLoginMessage);
            AdminList.save(adminEntry);
            AdminList.updateIndexLists();
            return true;
        } else {
            return false;
        }
    }
}
