import java.util.HashMap;
import java.util.Map;

public class MessageProcessor {
    private Map<Class<?>, Runnable> messageActions;

    public MessageProcessor() {
        messageActions = new HashMap<>();
    }

    public void processMessage(Object message) {
        messageActions.getOrDefault(message.getClass(), () -> {}).run();
    }

    public void addAction(Class<?> messageType, Runnable action) {
        messageActions.put(messageType, action);
    }

    public static void main(String[] args) {
        MessageProcessor processor = new MessageProcessor();

        // Define message types and their corresponding actions
        processor.addAction(MessageType.Location.class, () -> {
            // Action for MessageType.Location
            System.out.println("Processing location message");
        });

        processor.addAction(MessageType.Text.class, () -> {
            // Action for MessageType.Text
            System.out.println("Processing text message");
        });

        // Example usage
        processor.processMessage(new MessageType.Location());
        processor.processMessage(new MessageType.Text());
    }
}

class MessageType {
    static class Location {}
    static class Text {}
}
```

