def compare_list(list_one, list_two):
    common_list = []
    i, j = 0, 0
    while (i < len(list_one) and j < len(list_two)):
        if list_one[i] == list_two[j]:
            common_list.append(list_one[i])
            i += 1
            j += 1
        elif list_one[i] < list_two[j]:
            i += 1
        else:
            j += 1
    return common_list

def dec_to_binary(num):
    binary = ""
    while num > 0:
        binary+= str(num % 2)
        num = num // 2
    return binary[::-1]

