public class SocialNetwork {
    private Map<Integer, Integer> groupInvites = new HashMap<>(); // Map to store group invites with group ID as key and user ID as value

    public String removeGroupInvite(int groupID, int userID) {
        if (groupInvites.containsKey(groupID)) { // Check if the group ID exists in the map
            int senderID = groupInvites.get(groupID); // Get the user ID of the sender from the map
            if (senderID == userID) { // Check if the user is the sender of the invite
                groupInvites.remove(groupID); // Remove the group invite
                return "Group invite removed successfully";
            } else {
                return "You are not authorized to remove this group invite";
            }
        } else {
            return "Invalid group ID"; // Return error message for invalid group ID
        }
    }

    // Method to send a group invite
    public void sendGroupInvite(int groupID, int senderID) {
        groupInvites.put(groupID, senderID); // Add the group invite to the map
    }
}
