// LogEvent struct to capture metadata for log events
struct LogEvent {
    enum Level {
        case debug, info, warning, error
    }

    let level: Level
    let tag: String?
    let file: String
    let function: String
    let line: Int
}

// Logger class to log and print events
class Logger {
    private var loggedEvents: [LogEvent] = []

    func logEvent(_ event: LogEvent) {
        loggedEvents.append(event)
    }

    func printLog() {
        for event in loggedEvents {
            var logString = "\(event.level): "
            if let tag = event.tag {
                logString += "[\(tag)] "
            }
            logString += "File: \(event.file), Function: \(event.function), Line: \(event.line)"
            print(logString)
        }
    }
}

// Example usage
let logger = Logger()
let event1 = LogEvent(level: .debug, tag: "Networking", file: "NetworkManager.swift", function: "sendRequest", line: 42)
let event2 = LogEvent(level: .error, tag: nil, file: "DataProcessor.swift", function: "processData", line: 87)

logger.logEvent(event1)
logger.logEvent(event2)

logger.printLog()
