            {
                throw new ArgumentException("Star range is not provided.");
            }

            string[] rangeParts = starRange.Split('-');
            if (rangeParts.Length != 2 || !int.TryParse(rangeParts[0], out int lowerBound) || !int.TryParse(rangeParts[1], out int upperBound))
