class CreateUserService {
  async createUser(user: UserType): Promise<void> {
    const existingUser = await prismaClient.user.findUnique({
      where: {
        email: user.email,
      },
    })

    if (existingUser) {
      throw new AlreadyExistError('User with the same email already exists')
