def dice_game_simulation():
    initial_sum = sum(random.choices(range(1, 7), k=2))  # Simulate the initial dice roll
    if initial_sum in (7, 11):
        return "Player wins with the initial sum of {}".format(initial_sum)
    elif initial_sum in (2, 3, 12):
        return "Player loses with the initial sum of {}".format(initial_sum)
    else:
        print("Initial sum is {}. Rolling again...".format(initial_sum))
        while True:
            new_sum = sum(random.choices(range(1, 7), k=2))  # Roll the dice again
            if new_sum == initial_sum:
                return "Player wins by matching the initial sum of {}".format(initial_sum)
            elif new_sum == 7:
                return "Player loses by rolling a 7 before matching the initial sum"
