public class GraphVersionControl
{
    private Stack<GraphModel> versionStack = new Stack<GraphModel>();

    public GraphModel SetStencil(GraphModel graphModel, Stencil stencil, bool writeOnDisk)
    {
        Assert.IsNotNull(stencil);
        graphModel.Stencil = stencil;
        if (writeOnDisk)
            EditorUtility.SetDirty(this);
        versionStack.Push(graphModel); // Save the current version
        return graphModel;
    }

    public GraphModel RevertToPreviousVersion()
    {
        if (versionStack.Count > 1) // Ensure there is a previous version to revert to
        {
            versionStack.Pop(); // Discard the current version
            return versionStack.Peek(); // Return the previous version
        }
        else
        {
            return versionStack.Peek(); // Return the current version if no previous version exists
        }
    }
}
